function parseSection(section = "") {
  if (!section) {
    return [];
  }
  const matches = section.match(/\d+/g);
  if (!matches) {
    return [];
  }
  if (matches.length === 1) {
    return [Number(matches[0])];
  }
  const start = Number(matches[0]);
  const end = Number(matches[matches.length - 1]);
  const min = Math.min(start, end);
  const max = Math.max(start, end);
  const result = [];
  for (let zone = min; zone <= max; zone++) {
    result.push(zone);
  }
  return Array.from(new Set(result));
}

function isHomeSection(section = "") {
  if (!section) {
    return true;
  }
  if (section.includes("客")) {
    return false;
  }
  if (section.includes("主")) {
    return true;
  }
  return true;
}

function alignOdds(zoneData, isHome) {
  if (!zoneData) {
    return null;
  }
  if (isHome) {
    return {
      winMin: zoneData.winMin,
      winMax: zoneData.winMax,
      drawMin: zoneData.drawMin,
      drawMax: zoneData.drawMax,
      loseMin: zoneData.loseMin,
      loseMax: zoneData.loseMax,
      returnMin: zoneData.returnMin,
      returnMax: zoneData.returnMax,
    };
  }
  return {
    winMin: zoneData.loseMin,
    winMax: zoneData.loseMax,
    drawMin: zoneData.drawMin,
    drawMax: zoneData.drawMax,
    loseMin: zoneData.winMin,
    loseMax: zoneData.winMax,
    returnMin: zoneData.returnMin,
    returnMax: zoneData.returnMax,
  };
}

function lookupOdds(homeStrength, awayStrength, system) {
  const matches = ((zoneMap[homeStrength] || {})[awayStrength] || []);
  if (!matches.length) {
    return {
      success: false,
      error: `找不到 ${homeStrength} vs ${awayStrength} 的 Sheet2 匹配，请确认实力标签是否一致。`,
    };
  }
  const oddsTable = standardOdds[system];
  if (!oddsTable) {
    return {
      success: false,
      error: `体系 ${system} 不在标准赔率表中，请确认体系名称。`,
    };
  }
  const results = matches.map((entry) => {
    const section = entry.section || "";
    const rawValue = entry.rawValue || section;
    const zones = parseSection(section);
    const isHome = isHomeSection(section);
    const zoneDetails = zones.map((zone) => {
      const zoneData = oddsTable[zone];
      if (!zoneData) {
        return {
          zone,
          error: `体系 ${system} 缺少第 ${zone} 区赔率。`,
        };
      }
      const aligned = alignOdds(zoneData, isHome);
      return {
        zone,
        zoneLabel: zoneData.zoneLabel || `第 ${zone} 区`,
        odds: aligned,
      };
    });
    return {
      section,
      rawValue,
      isHomeSection: isHome,
      zones: zoneDetails,
    };
  });
  return {
    success: true,
    homeStrength,
    awayStrength,
    system,
    matches: results,
  };
}

function availableSystems() {
  return Object.keys(standardOdds);
}

// 直接暴露到全局window对象
window.OddsLookup = {
  lookupOdds: lookupOdds,
  availableSystems: availableSystems
};

console.log('✅ OddsLookup模块加载成功！');

